import torch


def run(logits, pre_idx, n_valid):
    k = pre_idx.shape[1]
    vals = logits[0, :n_valid].float()
    return torch.topk(vals, k, largest=True, sorted=True).indices.view(1, k).to(torch.int32)


def check_topk(ref_outputs, user_outputs, *, mandatory, tie, k, n):
    """Tie-robust top-k index-set check.

    mandatory: indices whose value is strictly greater than the k-th value
    tie: indices whose value equals the k-th value (any subset may fill the rest)
    """
    idx = user_outputs["indices"].flatten().to(torch.int64).cpu()
    problems = []
    if idx.numel() != k:
        problems.append(f"count {idx.numel()} != k={k}")
    else:
        if int(idx.min()) < 0 or int(idx.max()) >= n:
            problems.append("index out of range")
        if torch.unique(idx).numel() != k:
            problems.append("duplicate indices")
        mand = torch.tensor(mandatory, dtype=torch.int64)
        tie_t = torch.tensor(tie, dtype=torch.int64) if len(tie) else torch.empty(0, dtype=torch.int64)
        allowed = torch.cat([mand, tie_t])
        if not bool(torch.isin(idx, allowed).all()):
            problems.append("selected an index outside the true top-k set")
        if not bool(torch.isin(mand, idx).all()):
            problems.append("missing a mandatory top-k index")
    passed = len(problems) == 0
    return {"indices": {"passed": passed, "message": "; ".join(problems) or "ok"}}
